/*
1.繪製背景動畫  透明色0x001f
METRO_BG[], 8寬x64高 填滿64*64 重複由右到左移動
背景動畫運行3秒(delay參數A-可調)
2.繪製站牌
METRO_STATION1, 61x25   y=4   由右到左進入場景 直到圖片置中(圖片中心=螢幕中心)  
背景動畫運行5秒(參數B-可調)  站牌往左移出場景 ->
站牌移出場景後   背景動畫運行3秒(參數A) 

3.列車進站
METRO_TRAIN', 136x51px 此圖資為單節車廂 由左到右移入場景
當圖資最右邊車頭移動到X=32時 背景動畫開始緩慢停止  同時車廂往右移動,當車廂最左在X=0時
緊接著繪製下一節車廂(同樣圖資) 當地二節車廂的圖資的X432 = 螢幕的X32時  停止移動
等待3秒(參數A) 顯示時鐘

METRO_DOOR_OPEN()
先繪製內部 METRO_IN[]  21寬*42高   起始座標(11, 14)
水平翻轉繪圖  座標(31, 14)

畫車門 METRO_DOOR[]22寬*44高   (10,13)左車門 (31,13)右車門
車門開啟動畫效果   METRO_DOOR[]左車門原座標往左縮減X-1繪圖  也就是說車門22px寬 從X=0 繪製 下一偵從X=1   下一偵從X=2 直到X=22
這樣就是門檻起來往左縮減  右車門則反之

整個邏輯 也反之套用 變成一個 METRO_DOOR_CLOSE()


行人動作  往下走路 frame 0->1->(1水平翻轉) 
         往上走路 frame 2->3->(3水平翻轉)

行人sprite 圖資 METRO_P1[] 56*20    METRO_P2[] 56*19   METRO_P3[] 56*20
METRO_P4[] 64*19    METRO_P5[] 56*21   METRO_P6[] 64*20   METRO_P7[] 64*19  

行人出站  設1P位置 2P位置 ,生成範圍限制1P X=14~16 , 2P X=34~36    固定 y= 14 ~17
隨機抽取2行人 在1P /2P 位置   1P /2P  "先後陸續" 往下移動出站  當行人 往下移Y>22 可以 (有機率)左右偏移 移動 但主要還是往下
當1P 2P  的Y移動超過 23px 就生成下一組準備出站 整個出站總共會有2-3組

當所有人都出站後 等待 參數A秒  開始進站
邏輯則跟出站是相反方向  也就是從場景外移動到1P 2P位子 (後面一組到達位子後前1組就消失 避免重疊 最後會保留一組人的畫面)
當進站完成後 (時鐘停止繪圖) 等待 然後 啟動關門動畫 等待  鏡頭移到車頭(最右邊車頭在X32=)   BG背景 開始繼續由左往右 循序由慢到快移動 塑造列車移動的效果
持續30秒  進入下一次的進站循環     

*/






